-- 6. Schulz Air Plus 12 V: o compressor portátil para calibrar o pneu na garagem (review, 1337 palavras)
insert into public.posts (slug, title, subtitle, excerpt, body, cover_image_url, cover_image_alt, category_id, author_id, kind, review, comparison, product_category, product_subcategory, product_score, faq, quiz, status, publish_at, reading_time, seo_title, seo_description)
values (
  'schulz-air-plus-12v-compressor-portatil-para-calibrar-o-pneu-na-garagem',
  'Schulz Air Plus 12 V: o compressor portátil para calibrar o pneu na garagem',
  'Review do compressor de ar que liga no acendedor do carro: o que ele enche, quanto demora, o que o manual manda respeitar e para qual pai ele vale a pena.',
  'O Schulz Air Plus 12 V calibra pneu de carro, moto e bicicleta na garagem e socorre no acostamento. Nota 7,6: funciona, com limite de uso contínuo.',
  $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pneu murcho na manhã de segunda-feira, com a mulher e as crianças já no carro e o posto mais perto a dez minutos. Ou aquele pneu que perde um pouco de ar toda semana e que você completa só quando lembra. Um compressor portátil no porta-malas resolve os dois casos, e o Schulz Air Plus 12 V é o modelo de marca mais citado para isso no Brasil."}]},{"type":"paragraph","content":[{"type":"text","text":"Analisamos a ficha técnica e o manual da Schulz, o anúncio da Amazon Brasil e o que os compradores dizem fora da Amazon. Veredito: o "},{"type":"text","text":"Schulz Air Plus 12 V","marks":[{"type":"link","attrs":{"href":"/loja/schulz-air-plus-12v","class":null,"rel":null,"target":null}}]},{"type":"text","text":" faz o que promete, calibra os pneus do carro da família na garagem e salva o dia no acostamento; é mais caro que os genéricos, mas tem marca, peças e assistência. Nota 7,6. Ele entra no mesmo cantinho da garagem do "},{"type":"text","text":"kit básico de ferramentas da casa","marks":[{"type":"link","attrs":{"href":"/post/kit-basico-de-ferramentas-para-a-casa","class":null,"rel":null,"target":null}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Em 3 pontos"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Liga no acendedor de 12 V, tem manômetro e bicos para pneu de carro, moto, bicicleta, bola e colchão."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Calibrar é rápido; encher pneu vazio é em etapas, porque o manual limita o uso contínuo antes de uma pausa para esfriar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Marca com assistência técnica e peças no Brasil, o que os genéricos não têm; o preço reflete isso."}]}]}]},{"type":"fotosModelos","attrs":{"data":{"modelos":[{"slug":"schulz-air-plus-12v","name":"Schulz Air Plus 12 V","src":"","href":""}]}}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"O que ele enche e quanto demora"}]},{"type":"paragraph","attrs":{"class":"btn-comprar-wrap"},"content":[{"type":"text","text":"Comprar agora na Amazon","marks":[{"type":"link","attrs":{"href":"{AMAZON:schulz-air-plus-12v}","class":"btn-comprar","rel":"sponsored nofollow noopener","target":"_blank"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"O Air Plus é um compressor de pistão sem óleo, alimentado pelo acendedor de cigarros do carro, com manômetro na frente, mangueira curta com bico de rosca para a válvula do pneu e um jogo de adaptadores para bicicleta, bola e colchão. O cabo de alimentação, segundo a ficha, alcança as quatro rodas de um carro de passeio comum sem desconectar; em SUV grande, a roda traseira oposta pode ficar no limite."}]},{"type":"paragraph","content":[{"type":"text","text":"Completar a pressão de um pneu que perdeu dois ou três PSI leva pouco mais de um minuto por roda. Encher um pneu totalmente vazio é outra conversa: o manual limita o uso contínuo a alguns minutos antes de uma pausa obrigatória para o motor esfriar, e um pneu de carro de passeio pode pedir duas ou três etapas. Para caminhonete com pneu grande, o processo fica longo, e aí vale um compressor maior. Para o uso que o pai de família tem na garagem, o tempo é aceitável."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"O manômetro e a pressão certa"}]},{"type":"paragraph","content":[{"type":"text","text":"O manômetro é analógico, com escala em PSI e bar, e serve bem como referência. Em opiniões fora da Amazon aparece a queixa de leitura imprecisa em alguns exemplares; a solução barata é conferir de vez em quando num calibrador de posto ou num calibrador digital de bolso. A pressão certa dos pneus do seu carro está na etiqueta da porta do motorista ou no manual do veículo, não no compressor nem no pneu."}]},{"type":"paragraph","content":[{"type":"text","text":"Uma rotina que funciona: calibrar a cada quinze dias, com o pneu frio, antes de sair de casa, incluindo o estepe (que todo mundo esquece e que costuma estar murcho na hora da necessidade). Pneu na pressão certa gasta menos combustível, dura mais e freia melhor com as crianças no banco de trás."}]},{"type":"paragraph","attrs":{"class":"btn-comprar-wrap"},"content":[{"type":"text","text":"Comprar agora na Amazon","marks":[{"type":"link","attrs":{"href":"{AMAZON:schulz-air-plus-12v}","class":"btn-comprar","rel":"sponsored nofollow noopener","target":"_blank"}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Segurança: o que o manual manda respeitar"}]},{"type":"paragraph","content":[{"type":"text","text":"Três regras saem do manual e das reclamações de quem não as leu. Primeira: ligue o compressor com o motor do carro em funcionamento, para puxar a corrente do alternador e não descarregar a bateria. Segunda: respeite o tempo máximo de uso contínuo e a pausa para esfriar; o motor sem óleo esquenta rápido e é assim que a maioria dos compressores portáteis queima. Terceira: não ultrapasse a pressão recomendada do pneu, porque pneu com excesso de ar estoura mais fácil em buraco e lombada."}]},{"type":"paragraph","content":[{"type":"text","text":"O plugue de 12 V tem fusível, e a Schulz tem rede de assistência no país, o que os compressores genéricos de loja de autopeças não oferecem. O aparelho é barulhento (é um compressor de pistão), então calibre na garagem, não na madrugada com o bebê dormindo no quarto da frente."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ficha técnica"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Campo"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Valor informado pelo fabricante"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Modelo"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Schulz Air Plus 12 V"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Alimentação"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"12 V, pelo acendedor de cigarros do veículo"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Tipo"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Compressor de pistão sem óleo"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Manômetro"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Analógico, PSI e bar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Acessórios"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Bicos para bicicleta, bola e colchão; bolsa"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Uso contínuo"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Limitado; pausa para resfriamento (ver manual)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Garantia"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"Conforme o fabricante (consulte o anúncio)"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"O que dizem outros compradores"}]},{"type":"paragraph","content":[{"type":"text","text":"Procuramos padrões que se repetem em avaliações fora da Amazon (Reclame Aqui, Mercado Livre, Magalu e fóruns de automóveis). Os elogios mais frequentes: resolver o pneu murcho sem ir ao posto, o cabo que alcança as quatro rodas e a confiança na marca. As reclamações reais: o barulho alto e o manômetro impreciso em alguns exemplares. Nas reclamações de compressor que parou de funcionar, o padrão que aparece é o uso contínuo além do tempo do manual, enchendo pneu vazio de uma vez só."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Semáforo do pai: pneu e compressor no carro da família"}]},{"type":"callout","attrs":{"tone":"ok"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal verde: pneus calibrados a cada quinze dias com o pneu frio, estepe incluído, pressão conferida na etiqueta da porta e compressor guardado na bolsa com os bicos."}]}]},{"type":"callout","attrs":{"tone":"warn"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de atenção: pneu que perde ar toda semana (provável furo ou válvula), compressor que esquenta demais ou manômetro que marca diferente do posto: conserte o pneu na borracharia e confira o aparelho antes de confiar nele na estrada."}]}]},{"type":"callout","attrs":{"tone":"bad"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sinal de alerta: pneu com bolha, corte na lateral ou que murcha em minutos, ou estouro em movimento: não encha, não dirija; troque pelo estepe em local seguro ou chame o guincho, procure um borracheiro ou um mecânico de confiança e, se houve acidente com alguém ferido, o pronto-socorro vem antes do carro."}]}]},{"type":"paragraph","attrs":{"class":"btn-comprar-wrap"},"content":[{"type":"text","text":"Comprar agora na Amazon","marks":[{"type":"link","attrs":{"href":"{AMAZON:schulz-air-plus-12v}","class":"btn-comprar","rel":"sponsored nofollow noopener","target":"_blank"}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Variação de preço"}]},{"type":"paragraph","content":[{"type":"text","text":"O Schulz Air Plus 12 V costuma ficar na faixa de {FAIXA:schulz-air-plus-12v}. O preço varia com a versão (com ou sem lanterna e bolsa), com a loja e com as promoções de autopeças; os genéricos custam menos e os compressores digitais com desligamento automático, mais."}]},{"type":"paragraph","content":[{"type":"text","text":"Observação: a faixa é o preço consultado na internet como um todo (lojas, comparadores e site do fabricante), não apenas na Amazon. O valor do dia aparece ao clicar no botão de compra."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Para quem vale a pena (e para quem não)"}]},{"type":"paragraph","content":[{"type":"text","text":"Vale para o pai que quer calibrar os pneus do carro na garagem toda quinzena e ter socorro para pneu murcho na estrada, sem depender do posto, e que prefere pagar um pouco mais por marca e assistência. Veja a ficha completa e a review da loja em "},{"type":"text","text":"Schulz Air Plus 12 V","marks":[{"type":"link","attrs":{"href":"/loja/schulz-air-plus-12v","class":null,"rel":null,"target":null}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Não vale para quem tem caminhonete com pneu grande (o tempo de enchimento fica longo), para quem precisa de compressor para pintura ou ferramenta pneumática (isso é compressor de tanque, outra categoria) nem para quem não vai respeitar o tempo de descanso do manual. Para o kit de emergência completo do porta-malas, ele entra junto com triângulo, chave de roda e lanterna, e com a disciplina de quem monta o "},{"type":"text","text":"orçamento familiar","marks":[{"type":"link","attrs":{"href":"/post/orcamento-familiar-para-quem-vai-ser-pai","class":null,"rel":null,"target":null}}]},{"type":"text","text":" sem deixar a manutenção do carro para depois."}]},{"type":"paragraph","attrs":{"class":"btn-comprar-wrap"},"content":[{"type":"text","text":"Comprar agora na Amazon","marks":[{"type":"link","attrs":{"href":"{AMAZON:schulz-air-plus-12v}","class":"btn-comprar","rel":"sponsored nofollow noopener","target":"_blank"}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Como avaliamos"}]},{"type":"paragraph","content":[{"type":"text","text":"Análise baseada na ficha técnica e no manual da Schulz, no anúncio da Amazon Brasil e em opiniões de compradores fora da Amazon (Reclame Aqui, Mercado Livre, Magalu, fóruns de automóveis). Não fizemos teste físico. A nota é a média ponderada de cinco critérios com os pesos da categoria Carro e Moto: funcionalidade (30), instalação e praticidade (15), qualidade de construção (20), segurança e certificação (15) e custo-benefício (20). A nota é editorial e não é a estrela da Amazon; a faixa de preço vem de pesquisa em várias lojas, nunca de preço exato."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Outros reviews e comparativos"}]},{"type":"paragraph","content":[{"type":"text","text":"Continue no Pai Indica: o comparativo de "},{"type":"text","text":"parafusadeiras de 12 V","marks":[{"type":"link","attrs":{"href":"/pai-indica/bosch-gsr-120-ou-black-decker-ld12-ou-makita-hp333-parafusadeira-12v","class":null,"rel":null,"target":null}}]},{"type":"text","text":" para a garagem e a lista de "},{"type":"text","text":"5 livros de finanças pessoais para o pai de família","marks":[{"type":"link","attrs":{"href":"/pai-indica/5-livros-de-financas-pessoais-que-todo-pai-de-familia-deveria-ler","class":null,"rel":null,"target":null}}]},{"type":"text","text":". No blog, "},{"type":"text","text":"como dar limites sem gritar","marks":[{"type":"link","attrs":{"href":"/post/como-dar-limites-sem-gritar-autoridade-com-calma","class":null,"rel":null,"target":null}}]},{"type":"text","text":" os "},{"type":"text","text":"exames que todo homem deve fazer a partir dos 30 anos","marks":[{"type":"link","attrs":{"href":"/post/exames-que-todo-homem-deve-fazer-a-partir-dos-30-anos","class":null,"rel":null,"target":null}}]},{"type":"text","text":" e o "},{"type":"text","text":"treino de 20 minutos em casa para pais sem tempo","marks":[{"type":"link","attrs":{"href":"/post/treino-de-20-minutos-em-casa-para-pais-sem-tempo","class":null,"rel":null,"target":null}}]},{"type":"text","text":", para a hora em que a garagem vira academia."}]}]}$body$::jsonb,
  '/images/covers/schulz-air-plus-12v-compressor-portatil-para-calibrar-o-pneu-na-garagem.jpg',
  'Foto oficial do compressor portátil Schulz Air Plus 12 V',
  (select id from public.categories where slug = 'pai-indica'),
  coalesce((select id from auth.users where lower(email) = 'contato@vocacaodepai.com.br'), 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa'::uuid),
  'review',
  $rev${"product_slug":"schulz-air-plus-12v","score":7.6,"criteria":[{"name":"Funcionalidade","weight":30,"score":8,"comment":"Calibra pneu de carro, moto e bicicleta e enche bola e colchão; resolve o pneu murcho na garagem e no acostamento."},{"name":"Instalação e praticidade","weight":15,"score":8,"comment":"Liga no acendedor de 12 V; cabo e mangueira alcançam as quatro rodas de um carro comum."},{"name":"Qualidade de construção","weight":20,"score":7,"comment":"Corpo de plástico resistente, mas o manômetro analógico pede conferência."},{"name":"Segurança e certificação","weight":15,"score":7.5,"comment":"Fusível no plugue e marca com assistência; o ciclo de uso contínuo é limitado e precisa ser respeitado."},{"name":"Custo-benefício","weight":20,"score":7.5,"comment":"Mais caro que os genéricos, mas com marca, peças e assistência no Brasil."}],"pros":["Liga direto no acendedor de 12 V","Manômetro para conferir a pressão","Bicos para bicicleta, bola e colchão","Marca com assistência técnica no Brasil"],"cons":["Ciclo de uso contínuo limitado: precisa esfriar","Manômetro analógico pede conferência com calibrador","Barulhento","Não enche pneu de caminhonete grande com rapidez"],"ideal_for":"Pai que quer calibrar os pneus do carro na garagem toda quinzena e ter socorro para pneu murcho na estrada, sem depender do posto.","not_ideal_for":"Quem tem caminhonete com pneu grande ou precisa de compressor para pintura e ferramenta pneumática.","verdict":"O Schulz Air Plus 12 V faz o que promete: calibra os pneus do carro da família na garagem e salva o dia no acostamento. É mais caro que os genéricos, mas tem marca, peças e assistência. Respeite o tempo de descanso do motor e confira o manômetro de vez em quando.","how_we_evaluated":"Análise baseada na ficha técnica e no manual da Schulz, no anúncio da Amazon Brasil e em opiniões de compradores fora da Amazon (Reclame Aqui, Mercado Livre, Magalu, fóruns de automóveis). Não fizemos teste físico. Nota editorial: média ponderada de 5 critérios (pesos da categoria Carro e Moto).","sources":["schulz.com.br (ficha e manual)","Amazon Brasil (anúncio)","Reclame Aqui","Mercado Livre","Magalu"],"other_buyers":{"intro":"Procuramos padrões que se repetem em avaliações fora da Amazon.","praises":["Resolve o pneu murcho sem ir ao posto","Cabo longo alcança as quatro rodas","Marca conhecida"],"complaints":["Barulho alto","Manômetro impreciso em alguns exemplares"],"sources":["Reclame Aqui","Mercado Livre","Magalu"],"none_found":false}}$rev$::jsonb,
  null,
  'carro-e-moto',
  'emergencia-e-manutencao',
  7.6,
  $faq$[{"question":"Ele enche um pneu totalmente vazio?","answer":"Enche, mas devagar e em etapas: o manual limita o uso contínuo a alguns minutos antes de uma pausa para esfriar. Para pneu de carro de passeio, é questão de paciência; para pneu de caminhonete grande, pode levar várias pausas. Para calibrar (completar a pressão), é rápido."},{"question":"O manômetro é confiável?","answer":"É um manômetro analógico de uso doméstico. Serve para referência; confira a pressão de vez em quando num calibrador de posto ou num calibrador digital de bolso, que custa pouco. A pressão certa do seu carro está na etiqueta da porta do motorista."},{"question":"Posso ligar com o carro desligado?","answer":"O manual recomenda ligar com o motor em funcionamento, para o compressor puxar a corrente do alternador e não da bateria. Com o carro desligado por muito tempo, a bateria pode não dar partida depois."},{"question":"Serve para moto e bicicleta?","answer":"Sim. Vem com bicos adaptadores para bicicleta (válvula fina), bola e colchão inflável, além do bico de pneu de carro e moto. Guarde os bicos na própria bolsa do compressor para não perder."},{"question":"Vale mais que um compressor genérico de loja de autopeças?","answer":"Custa mais, e o que se paga é marca, peças de reposição e assistência técnica no Brasil. Se o compressor vai viver no porta-malas por anos, isso faz diferença; se é para uso raro, um genérico pode resolver."}]$faq$::jsonb,
  $quiz$[{"question":"Onde o Schulz Air Plus 12 V é ligado?","options":["Na tomada de casa","No acendedor de cigarros do carro","Na bateria por garras","Em pilhas"],"correct":1,"explanation":"O modelo usa o plugue de 12 V do acendedor de cigarros, com fusível no próprio plugue."},{"question":"Por que o manual limita o tempo de uso contínuo?","options":["Para economizar bateria do carro","Porque o motor esquenta e precisa esfriar","Porque o manômetro descalibra","Não há limite"],"correct":1,"explanation":"O motor sem óleo esquenta rápido; o descanso evita queimar o compressor."},{"question":"Onde está a pressão certa dos pneus do seu carro?","options":["No próprio pneu","Na etiqueta da porta do motorista ou no manual do carro","No manômetro do compressor","No site da Schulz"],"correct":1,"explanation":"A pressão recomendada é do fabricante do carro, na etiqueta da porta ou no manual."}]$quiz$::jsonb,
  'published',
  now() - interval '0 days',
